        You are a programming expert. 
        You will be provided with a patch used to fix a bug. 
        Based on the commit message and modifications in the patch, you need to analyze the root cause of the bug in detail. 

        Here is the patch content:
        From 7df648f1cff55fa9126d444c9f70083434b0d213 Mon Sep 17 00:00:00 2001
From: Howard Pritchard <hppritcha@gmail.com>
Date: Tue, 6 Jan 2015 11:31:12 -0700
Subject: [PATCH] btl/openib: fix problems from commit b3617e73

For systems with OFED's lacking XRC support, commit b3617e73
broke the build of the openib btl.  This commit addresses
the issues introduced by this commit.
---
 opal/mca/btl/openib/connect/btl_openib_connect_udcm.c | 5 +++--
 1 file changed, 3 insertions(+), 2 deletions(-)

diff --git a/opal/mca/btl/openib/connect/btl_openib_connect_udcm.c b/opal/mca/btl/openib/connect/btl_openib_connect_udcm.c
index fc801e38b3..c22e95e6cc 100644
--- a/opal/mca/btl/openib/connect/btl_openib_connect_udcm.c
+++ b/opal/mca/btl/openib/connect/btl_openib_connect_udcm.c
@@ -2534,6 +2534,7 @@ static int udcm_xrc_recv_qp_connect (mca_btl_openib_endpoint_t *lcl_ep)
         return OPAL_SUCCESS;
     }
 #else
+    int ret;
     BTL_VERBOSE(("Connecting receive qp: %d", lcl_ep->xrc_recv_qp_num));
     ret = ibv_reg_xrc_rcv_qp(openib_btl->device->xrc_domain, lcl_ep->xrc_recv_qp_num);
     if (ret) { /* failed to regester the qp, so it is already die and we should create new one */
@@ -2578,10 +2579,10 @@ static int udcm_xrc_recv_qp_create (mca_btl_openib_endpoint_t *lcl_ep, udcm_msg_
     memset(&qp_init_attr, 0, sizeof(struct ibv_qp_init_attr));
     /* Only xrc_domain is required, all other are ignored */
     qp_init_attr.xrc_domain = openib_btl->device->xrc_domain;
-    ret = ibv_create_xrc_rcv_qp(&qp_init_attr, &lcl_ep->xrc_recv_qp->qp_num);
+    ret = ibv_create_xrc_rcv_qp(&qp_init_attr, &lcl_ep->xrc_recv_qp_num);
     if (ret) {
         BTL_ERROR(("Error creating XRC recv QP[%x], errno says: %s [%d]",
-                   lcl_ep->xrc_recv_qp->qp_num, strerror(ret), ret));
+                   lcl_ep->xrc_recv_qp_num, strerror(ret), ret));
         return OPAL_ERROR;
     }
 #endif
-- 
